-- =====================================================================
-- Locale_406.lua — v4.0.6 release notes and feature highlights
-- =====================================================================

TomoMod_RegisterLocale("enUS", {
    ["wn_406_forever_detection"] = "New — TomoMod now recognizes WoW: Forever as its own client flavour by combining the modern project identifier with the 1.60 version line or interface 16001, without mistaking Classic Era or Mists Classic for it.",
    ["wn_406_forever_modules"] = "Changed — Mythic+, Housing, Prey Tracker, Compass, Consumables, Skyriding and World Quests are disabled safely on Forever before initialization and forced off in defaults, profiles, imports and live toggles.",
    ["wn_406_forever_interface"] = "Changed — Unavailable option pages, QOL tabs and the Mythic+ Studio entry are removed on Forever. A login notice explains the limitations, and /tm flavor reports the detected client and compatibility decisions.",
    ["wn_406_forever_validation"] = "Internal — A dedicated 167-check bench validates client detection, database enforcement, manifest/default consistency and source guards for every blocked module.",
    ["wn_406_forever_actionbars"] = "Fixed — Owned Action Bars now skip the unavailable Challenge Mode events on WoW: Forever. Invalid event registration could stop initialization before any bar was built, leaving every custom action bar missing even though the module was marked initialized.",
    ["wn_406_minimap_layout_drag"] = "Fixed — The minimap overlay is now a real TomoLayout drag surface instead of a visual layer above the native frame. The minimap can be selected and moved reliably from Layout mode even when Blizzard Edit Mode has not loaded yet.",
    ["wn_406_minimap_drag_guard"] = "Changed — Minimap position protection pauses while it is being dragged, saves the final location on release and then resumes guarding against later Blizzard layout overrides.",
    ["wn_406_gear_weight_import"] = "New — TomoGear V1.2 can import Pawn v1, Ask Mr. Robot and compatible key=value stat scales for the current specialization. Primary stat, Stamina, Critical Strike, Haste, Mastery and Versatility are supported.",
    ["wn_406_gear_import_gui"] = "Fixed — The complete TomoGear import workflow is restored in the Gear Advisor QOL tab, including Imported mode, the multiline scale editor, status feedback and import/removal actions. Profile and status text now refresh immediately.",
    ["wn_406_gear_import_validation"] = "New — Each specialization keeps its own imported profile. Class, specialization and primary-stat mismatches are rejected, unsupported values are ignored, and item level has no implicit weight unless ItemLevel= is provided.",
    ["wn_406_gear_independent_db"] = "Changed — TomoGear preferences and weights now live in the dedicated TomoGearDB SavedVariable, independently from TomoMod profiles and imports. Existing Gear Advisor settings are migrated automatically once.",
    ["wn_406_gear_signed_percent"] = "Changed — Item tooltips now show signed percentages for upgrades, downgrades and equal items in green, red and neutral colours. The minimum-upgrade threshold applies only to the bag arrow.",
    ["wn_406_gear_itemref"] = "Fixed — Opening an item link from chat no longer raises an 'attempt to call a nil value' error when ItemRefTooltip reaches the item post-processor without an addon-accessible AddLine method on some Midnight builds.",
    ["wn_406_gear_tooltip_guard"] = "Changed — TomoGear now checks tooltip line support and isolates every advice-line insertion. Unsupported tooltip implementations are skipped safely while the normal GameTooltip path remains unchanged.",
    ["wn_406_mplus_score_totals"] = "Fixed — TomoScore now reads damage, healing and interrupts from the run-wide Overall Damage Meter sessions with the correct meter types. Players are matched by readable GUID or name, so the summary no longer remains at zero because it queried a source breakdown instead of the player list.",
    ["wn_406_secret_value_safety"] = "Fixed — Mythic+ names, textures, timers, Vault item levels, run history and death GUIDs, plus Nameplate quest GUIDs, are checked before comparison, formatting or table indexing. Protected data now falls back safely instead of raising an error.",
    ["wn_406_leveling_max_level"] = "Fixed — The leveling bar now respects level 60 on WoW: Forever and the client-reported Retail cap, including level 90 on Midnight. Reaching the cap hides the bar immediately and restores Blizzard's XP bar without a nil-global error.",
    ["wn_406_localized_commands_diag"] = "Changed — Module, backup, layout, resolution and help command feedback is now localized in all six supported languages. /tdm diag also runs its synchronous and next-frame Damage Meter readability probe correctly instead of silently doing nothing.",
    ["wn_406_actionbar_diagnostics"] = "New — Diagnostics reports now include a read-only Action Bars section showing each bar's container state, secure visibility driver and current result, anchor, mover, button totals and first-button action and icon data.",
    ["wn_406_actionbar_probe_safety"] = "Changed — Hard-hide conditions, C_ActionBar state and silenced SafeCall failures are now reported explicitly. The probe remains safe in combat and degrades cleanly when APIs, frame methods or values are unavailable.",
    ["wn_406_actionbar_secure_wiring"] = "New — The Action Bars probe now tests Execute, SetFrameRef and restricted GetFrameRef directly, and reports each bar's secure layout references, protection state and first-button action attributes. This separates a client-wide secure-handler failure from wiring lost during bar construction.",
    ["wn_406_early_error_capture"] = "Changed — Diagnostics now captures relevant TomoMod and restricted-handler errors raised from initial loading through PLAYER_LOGIN, forwards them to the previous handler and marks retained entries as [during load]. ADDON_LOADED failures can no longer produce a misleading zero-error report.",
    ["wn_406_actionbar_compat_gate"] = "Fixed — WoW: Forever builds without Blizzard's restricted-code compiler now stop the owned Action Bars engine before initialization and keep the Totem Bar dormant. Blizzard's native bars remain available instead of being replaced by custom bars whose secure layout cannot run.",
    ["wn_406_actionbar_retail_profile_hotfix"] = "Fixed — Retail profiles with a disabled saved Action Bars master toggle no longer lose every owned bar after a reload. The Forever compatibility hotfix preserves the engine's historical Retail behaviour and blocks it only when the client cannot run restricted code.",
    ["wn_406_actionbar_block_diagnostics"] = "Changed — The Forever gate is capability-based, preserves Action Bars and Totem Bar settings, and releases automatically if restricted execution returns. Diagnostics reports the client gate separately from the saved master-toggle value.",
    ["wn_406_slider_decimal_input"] = "Fixed — Right-click slider entry now accepts decimal commas such as 0,5 instead of snapping to the minimum. Its value-entry and Ctrl-click reset hint is localized in all six supported languages.",
    ["wn_406_astralforge_cleanup"] = "Fixed — Astral Forge no longer creates a premature global CommitFrameEdit wrapper around a local function that has not been declared yet. Nameplate parity previews continue to refresh through the existing subject rebuild path.",
    ["wn_406_asset_cleanup"] = "Changed — The six active icon-skin textures were refreshed, while obsolete class-power artwork, the unused proc-glow mask and the retired Taluani sound were removed from the package.",
    ["wn_406_static_analysis"] = "Internal — Luacheck now recognizes current addon globals and the isolated TUI and test environments. Eight resolved protected-value findings were removed from the release baseline.",
})

TomoMod_RegisterLocale("frFR", {
    ["wn_406_forever_detection"] = "Nouveauté — TomoMod reconnaît maintenant WoW : Forever comme un client distinct en combinant l'identifiant du projet moderne avec la version 1.60 ou l'interface 16001, sans le confondre avec Classic Era ou Mists Classic.",
    ["wn_406_forever_modules"] = "Modification — Mythique+, Logement, Traqueur de proie, Boussole, Consommables, Vol dynamique et Quêtes du monde sont désactivés proprement sur Forever avant leur initialisation et forcés à l'arrêt dans les valeurs par défaut, profils, imports et bascules directes.",
    ["wn_406_forever_interface"] = "Modification — Les pages d'options, onglets QOL et l'entrée du Studio Mythique+ indisponibles sont retirés sur Forever. Un message de connexion explique les limitations et /tm flavor indique le client détecté ainsi que les décisions de compatibilité.",
    ["wn_406_forever_validation"] = "Interne — Un banc dédié de 167 contrôles valide la détection du client, l'application aux données, la cohérence manifeste/valeurs par défaut et les gardes de chaque module bloqué.",
    ["wn_406_forever_actionbars"] = "Correction — Les barres d'action gérées ignorent désormais les événements de mode Défi indisponibles sur WoW : Forever. L'enregistrement d'un événement invalide pouvait interrompre l'initialisation avant la création de la moindre barre, laissant toutes les barres personnalisées absentes alors que le module était marqué comme initialisé.",
    ["wn_406_minimap_layout_drag"] = "Correction — La superposition de la minimap est maintenant une véritable surface de déplacement TomoLayout plutôt qu'une simple couche visuelle au-dessus du cadre natif. La minimap peut être sélectionnée et déplacée de façon fiable depuis le mode Layout, même si le mode Édition de Blizzard n'est pas encore chargé.",
    ["wn_406_minimap_drag_guard"] = "Modification — La protection de position de la minimap se met en pause pendant son déplacement, enregistre l'emplacement final au relâchement puis reprend sa protection contre les modifications ultérieures de Blizzard.",
    ["wn_406_gear_weight_import"] = "Nouveauté — TomoGear V1.2 peut importer des échelles Pawn v1, Ask Mr. Robot et key=value compatibles pour la spécialisation actuelle. La caractéristique principale, l'Endurance, le Critique, la Hâte, la Maîtrise et la Polyvalence sont pris en charge.",
    ["wn_406_gear_import_gui"] = "Correction — Le flux d'import complet de TomoGear est restauré dans l'onglet QOL du Conseiller d'équipement, avec le mode Importé, l'éditeur multiligne, le statut et les actions d'importation ou de suppression. Le profil et le statut s'actualisent immédiatement.",
    ["wn_406_gear_import_validation"] = "Nouveauté — Chaque spécialisation conserve son propre profil importé. Les incompatibilités de classe, de spécialisation ou de caractéristique principale sont refusées, les valeurs non prises en charge sont ignorées et le niveau d'objet ne reçoit aucun poids implicite sans ItemLevel=.",
    ["wn_406_gear_independent_db"] = "Modification — Les préférences et les poids de TomoGear résident maintenant dans la variable sauvegardée dédiée TomoGearDB, indépendamment des profils et imports TomoMod. Les anciens réglages du conseiller sont migrés automatiquement une seule fois.",
    ["wn_406_gear_signed_percent"] = "Modification — Les infobulles affichent maintenant un pourcentage signé pour les améliorations, régressions et objets équivalents, respectivement en vert, rouge et neutre. Le seuil minimal ne s'applique plus qu'à la flèche des sacs.",
    ["wn_406_gear_itemref"] = "Correction — Ouvrir un lien d'objet depuis la discussion ne provoque plus d'erreur 'attempt to call a nil value' lorsque ItemRefTooltip atteint le post-traitement des objets sans méthode AddLine accessible aux addons sur certaines versions de Midnight.",
    ["wn_406_gear_tooltip_guard"] = "Modification — TomoGear vérifie désormais que l'infobulle accepte l'ajout de lignes et isole chaque insertion de conseil. Les implémentations incompatibles sont ignorées proprement tandis que le fonctionnement normal de GameTooltip reste inchangé.",
    ["wn_406_mplus_score_totals"] = "Correction — TomoScore lit désormais les dégâts, soins et interruptions dans les sessions globales du Damage Meter avec les bons types de mesure. Les joueurs sont associés par GUID lisible ou par nom, si bien que le résumé ne reste plus à zéro à cause d'une requête sur le détail d'une source au lieu de la liste des joueurs.",
    ["wn_406_secret_value_safety"] = "Correction — Les noms, textures et chronos Mythique+, les niveaux d'objet du coffre, l'historique des clés et les GUID de mort, ainsi que les GUID de quête des Nameplates, sont vérifiés avant toute comparaison, mise en forme ou indexation. Les données protégées utilisent maintenant un repli sûr au lieu de provoquer une erreur.",
    ["wn_406_leveling_max_level"] = "Correction — La barre de progression respecte maintenant le niveau 60 sur WoW : Forever et le plafond Retail indiqué par le client, dont le niveau 90 sur Midnight. Atteindre le plafond masque immédiatement la barre et restaure celle de Blizzard sans erreur de globale nil.",
    ["wn_406_localized_commands_diag"] = "Modification — Les retours des commandes de modules, sauvegarde, disposition, résolution et aide sont maintenant traduits dans les six langues prises en charge. /tdm diag exécute aussi correctement son contrôle de lisibilité du Damage Meter immédiatement puis à l'image suivante, au lieu de ne rien faire.",
    ["wn_406_actionbar_diagnostics"] = "Nouveauté — Les rapports de diagnostic incluent maintenant une section Barres d'action en lecture seule indiquant l'état du conteneur de chaque barre, son pilote de visibilité sécurisé et son résultat actuel, son ancre, son cadre de déplacement, le nombre de boutons ainsi que les données d'action et d'icône du premier bouton.",
    ["wn_406_actionbar_probe_safety"] = "Modification — Les conditions de masquage forcé, l'état de C_ActionBar et les échecs SafeCall silencieux sont maintenant signalés explicitement. La sonde reste sûre en combat et se dégrade proprement lorsque des API, méthodes de cadre ou valeurs sont indisponibles.",
    ["wn_406_actionbar_secure_wiring"] = "Nouveauté — La sonde des barres d'action teste maintenant directement Execute, SetFrameRef et GetFrameRef en environnement restreint, puis indique les références sécurisées de disposition, l'état de protection et les attributs d'action du premier bouton. Elle distingue ainsi une panne générale du gestionnaire sécurisé d'un câblage perdu pendant la création des barres.",
    ["wn_406_early_error_capture"] = "Modification — Le diagnostic capture désormais les erreurs TomoMod et du gestionnaire restreint depuis le chargement initial jusqu'à PLAYER_LOGIN, les transmet au gestionnaire précédent et marque les entrées conservées [during load]. Une erreur à ADDON_LOADED ne peut plus produire un rapport trompeur sans aucune erreur.",
    ["wn_406_actionbar_compat_gate"] = "Correction — Les versions de WoW : Forever dépourvues du compilateur de code restreint de Blizzard arrêtent maintenant le moteur des barres d'action gérées avant son initialisation et laissent la barre des totems inactive. Les barres natives de Blizzard restent disponibles au lieu d'être remplacées par des barres personnalisées dont la disposition sécurisée ne peut pas fonctionner.",
    ["wn_406_actionbar_retail_profile_hotfix"] = "Correction — Les profils Retail dont le bouton maître enregistré des barres d'action est désactivé ne perdent plus toutes leurs barres gérées après un rechargement. Le correctif de compatibilité Forever préserve le comportement historique sur Retail et ne bloque le moteur que si le client ne peut pas exécuter le code restreint.",
    ["wn_406_actionbar_block_diagnostics"] = "Modification — La garde Forever repose sur les capacités du client, conserve les réglages des barres d'action et de la barre des totems, puis se désactive automatiquement si l'exécution restreinte revient. Le diagnostic affiche séparément la garde client et la valeur enregistrée du bouton maître.",
    ["wn_406_slider_decimal_input"] = "Correction — La saisie directe des curseurs par clic droit accepte maintenant les virgules décimales comme 0,5 au lieu de ramener la valeur au minimum. L'infobulle de saisie et de réinitialisation par Ctrl+clic est traduite dans les six langues prises en charge.",
    ["wn_406_astralforge_cleanup"] = "Correction — Astral Forge ne crée plus prématurément de wrapper global CommitFrameEdit autour d'une fonction locale pas encore déclarée. Les aperçus de parité des Nameplates continuent de s'actualiser par le chemin existant de reconstruction du sujet.",
    ["wn_406_asset_cleanup"] = "Modification — Les six textures actives des skins d'icônes ont été actualisées, tandis que les anciens visuels de ressources de classe, le masque de halo inutilisé et le son Taluani retiré ont été supprimés du paquet.",
    ["wn_406_static_analysis"] = "Interne — Luacheck reconnaît maintenant les globales actuelles de l'addon ainsi que les environnements isolés de TUI et des tests. Huit alertes de valeurs protégées résolues ont été retirées de la baseline de publication.",
})

TomoMod_RegisterLocale("deDE", {
    ["wn_406_forever_detection"] = "Neu — TomoMod erkennt WoW: Forever jetzt als eigenen Clienttyp, indem die moderne Projektkennung mit der Versionslinie 1.60 oder Interface 16001 kombiniert wird, ohne Classic Era oder Mists Classic damit zu verwechseln.",
    ["wn_406_forever_modules"] = "Geändert — Mythisch+, Wohnen, Beutejäger, Kompass, Verbrauchsgüter, dynamisches Fliegen und Weltquests werden auf Forever vor der Initialisierung sicher deaktiviert und in Standardwerten, Profilen, Importen und Live-Schaltern ausgeschaltet gehalten.",
    ["wn_406_forever_interface"] = "Geändert — Nicht verfügbare Optionsseiten, QOL-Reiter und der Eintrag für das Mythisch+-Studio werden auf Forever entfernt. Ein Hinweis beim Anmelden erklärt die Einschränkungen; /tm flavor zeigt den erkannten Client und die Kompatibilitätsentscheidungen.",
    ["wn_406_forever_validation"] = "Intern — Ein eigener Prüfstand mit 167 Kontrollen validiert Clienterkennung, Datenbankdurchsetzung, Konsistenz von Manifest und Standardwerten sowie die Schutzabfragen aller blockierten Module.",
    ["wn_406_forever_actionbars"] = "Behoben — Die verwalteten Aktionsleisten überspringen nun die in WoW: Forever nicht verfügbaren Herausforderungsmodus-Ereignisse. Die Registrierung eines ungültigen Ereignisses konnte die Initialisierung vor dem Erstellen einer Leiste abbrechen, obwohl das Modul bereits als initialisiert markiert war.",
    ["wn_406_minimap_layout_drag"] = "Behoben — Die Minimap-Überlagerung ist jetzt eine echte TomoLayout-Ziehfläche statt nur einer sichtbaren Ebene über dem nativen Fenster. Die Minimap lässt sich im Layoutmodus zuverlässig auswählen und verschieben, selbst wenn Blizzards Bearbeitungsmodus noch nicht geladen wurde.",
    ["wn_406_minimap_drag_guard"] = "Geändert — Der Positionsschutz der Minimap pausiert während des Verschiebens, speichert beim Loslassen den endgültigen Ort und schützt danach wieder vor späteren Layout-Überschreibungen durch Blizzard.",
    ["wn_406_gear_weight_import"] = "Neu — TomoGear V1.2 kann Pawn-v1-, Ask-Mr.-Robot- und kompatible key=value-Attributgewichtungen für die aktuelle Spezialisierung importieren. Primärattribut, Ausdauer, Krit, Tempo, Meisterschaft und Vielseitigkeit werden unterstützt.",
    ["wn_406_gear_import_gui"] = "Behoben — Der vollständige TomoGear-Importablauf ist im QOL-Bereich des Ausrüstungsberaters wiederhergestellt, einschließlich Importmodus, mehrzeiligem Skaleneditor, Statusanzeige sowie Import- und Entfernen-Aktionen. Profil und Status werden sofort aktualisiert.",
    ["wn_406_gear_import_validation"] = "Neu — Jede Spezialisierung behält ihr eigenes importiertes Profil. Unpassende Klassen, Spezialisierungen oder Primärattribute werden abgelehnt, nicht unterstützte Werte ignoriert und die Gegenstandsstufe erhält ohne ItemLevel= kein stillschweigendes Gewicht.",
    ["wn_406_gear_independent_db"] = "Geändert — TomoGear-Einstellungen und -Gewichtungen liegen jetzt unabhängig von TomoMod-Profilen und -Importen in der eigenen gespeicherten Variable TomoGearDB. Vorhandene Berater-Einstellungen werden einmalig automatisch übernommen.",
    ["wn_406_gear_signed_percent"] = "Geändert — Gegenstands-Tooltips zeigen jetzt vorzeichenbehaftete Prozentwerte für Verbesserungen, Verschlechterungen und gleichwertige Gegenstände in Grün, Rot beziehungsweise neutral an. Der Mindestwert gilt nur noch für den Taschenpfeil.",
    ["wn_406_gear_itemref"] = "Behoben — Beim Öffnen eines Gegenstandslinks aus dem Chat tritt kein Fehler 'attempt to call a nil value' mehr auf, wenn ItemRefTooltip auf manchen Midnight-Versionen den Gegenstands-Nachbearbeiter ohne eine für Addons zugängliche AddLine-Methode erreicht.",
    ["wn_406_gear_tooltip_guard"] = "Geändert — TomoGear prüft jetzt, ob ein Tooltip das Hinzufügen von Zeilen unterstützt, und sichert jedes Einfügen eines Hinweises einzeln ab. Nicht unterstützte Tooltip-Implementierungen werden sicher übersprungen, während der normale GameTooltip-Pfad unverändert bleibt.",
    ["wn_406_mplus_score_totals"] = "Behoben — TomoScore liest Schaden, Heilung und Unterbrechungen jetzt aus den laufweiten Overall-Sitzungen des Damage Meters und verwendet die richtigen Messarten. Spieler werden über lesbare GUIDs oder Namen zugeordnet, sodass die Zusammenfassung nicht mehr bei null bleibt, weil statt der Spielerliste eine Quellaufschlüsselung abgefragt wurde.",
    ["wn_406_secret_value_safety"] = "Behoben — Mythisch+-Namen, Texturen, Zeitlimits, Tresor-Gegenstandsstufen, Laufverlauf und Todes-GUIDs sowie Quest-GUIDs der Namensplaketten werden vor Vergleichen, Formatierung oder Tabellenzugriff geprüft. Geschützte Daten verwenden nun einen sicheren Ersatz, statt Fehler auszulösen.",
    ["wn_406_leveling_max_level"] = "Behoben — Die Erfahrungsleiste berücksichtigt jetzt Stufe 60 in WoW: Forever und die vom Retail-Client gemeldete Höchststufe, einschließlich Stufe 90 in Midnight. Beim Erreichen der Höchststufe verschwindet sie sofort und stellt Blizzards Erfahrungsleiste ohne Nil-Global-Fehler wieder her.",
    ["wn_406_localized_commands_diag"] = "Geändert — Rückmeldungen zu Modul-, Sicherungs-, Layout-, Auflösungs- und Hilfebefehlen sind jetzt in allen sechs unterstützten Sprachen lokalisiert. /tdm diag führt seine Lesbarkeitsprüfung des Damage Meters nun sofort und im nächsten Frame korrekt aus, statt still nichts zu tun.",
    ["wn_406_actionbar_diagnostics"] = "Neu — Diagnoseberichte enthalten jetzt einen schreibgeschützten Abschnitt für Aktionsleisten. Er zeigt für jede Leiste den Containerstatus, den sicheren Sichtbarkeitstreiber mit aktuellem Ergebnis, Anker, Verschieber, Schaltflächenanzahl sowie Aktions- und Symboldaten der ersten Schaltfläche.",
    ["wn_406_actionbar_probe_safety"] = "Geändert — Bedingungen zum erzwungenen Ausblenden, der C_ActionBar-Status und unterdrückte SafeCall-Fehler werden nun ausdrücklich gemeldet. Die Prüfung bleibt im Kampf sicher und arbeitet kontrolliert weiter, wenn APIs, Fenstermethoden oder Werte nicht verfügbar sind.",
    ["wn_406_actionbar_secure_wiring"] = "Neu — Die Aktionsleistenprüfung testet Execute, SetFrameRef und das eingeschränkte GetFrameRef jetzt direkt und meldet die sicheren Layout-Referenzen jeder Leiste, ihren Schutzstatus sowie die Aktionsattribute der ersten Schaltfläche. Dadurch lässt sich ein allgemeiner Fehler des sicheren Handlers von einer beim Leistenaufbau verlorenen Verknüpfung unterscheiden.",
    ["wn_406_early_error_capture"] = "Geändert — Die Diagnose erfasst relevante TomoMod- und eingeschränkte Handlerfehler nun vom ersten Laden bis PLAYER_LOGIN, leitet sie an den vorherigen Fehlerhandler weiter und kennzeichnet gespeicherte Einträge mit [during load]. Fehler während ADDON_LOADED können keinen irreführenden Bericht mit null Fehlern mehr erzeugen.",
    ["wn_406_actionbar_compat_gate"] = "Behoben — WoW-Forever-Versionen ohne Blizzards Compiler für eingeschränkten Code stoppen die eigenen Aktionsleisten jetzt vor der Initialisierung und lassen die Totemleiste inaktiv. Blizzards native Leisten bleiben verfügbar, statt durch eigene Leisten ersetzt zu werden, deren sicheres Layout nicht ausgeführt werden kann.",
    ["wn_406_actionbar_retail_profile_hotfix"] = "Behoben — Bei Retail-Profilen mit gespeichertem, deaktiviertem Aktionsleisten-Hauptschalter verschwinden nach einem Neuladen nicht mehr alle eigenen Leisten. Der Forever-Kompatibilitätsfix bewahrt das bisherige Retail-Verhalten und blockiert den Motor nur, wenn der Client keinen eingeschränkten Code ausführen kann.",
    ["wn_406_actionbar_block_diagnostics"] = "Geändert — Die Forever-Sperre basiert auf den Fähigkeiten des Clients, behält die Einstellungen für Aktions- und Totemleisten bei und wird automatisch aufgehoben, sobald die eingeschränkte Ausführung zurückkehrt. Die Diagnose meldet die Clientsperre und den gespeicherten Hauptschalter getrennt.",
    ["wn_406_slider_decimal_input"] = "Behoben — Die direkte Werteingabe per Rechtsklick akzeptiert jetzt Dezimalkommas wie 0,5, statt den Regler auf den Mindestwert zu setzen. Der Hinweis zur Eingabe und zum Zurücksetzen per Strg+Klick ist in allen sechs unterstützten Sprachen lokalisiert.",
    ["wn_406_astralforge_cleanup"] = "Behoben — Astral Forge erstellt keinen verfrühten globalen CommitFrameEdit-Wrapper mehr um eine noch nicht deklarierte lokale Funktion. Die Paritätsvorschau der Namensplaketten wird weiterhin über den bestehenden Neuaufbau des Subjekts aktualisiert.",
    ["wn_406_asset_cleanup"] = "Geändert — Die sechs aktiven Texturen der Icon-Skins wurden erneuert; veraltete Klassenressourcen-Grafiken, die ungenutzte Proc-Glow-Maske und der ausgemusterte Taluani-Sound wurden aus dem Paket entfernt.",
    ["wn_406_static_analysis"] = "Intern — Luacheck erkennt jetzt die aktuellen Addon-Globalen sowie die isolierten TUI- und Testumgebungen. Acht behobene Funde zu geschützten Werten wurden aus der Release-Baseline entfernt.",
})

TomoMod_RegisterLocale("esES", {
    ["wn_406_forever_detection"] = "Novedad — TomoMod ahora reconoce WoW: Forever como un tipo de cliente propio al combinar el identificador del proyecto moderno con la versión 1.60 o la interfaz 16001, sin confundirlo con Classic Era ni Mists Classic.",
    ["wn_406_forever_modules"] = "Cambio — Mítico+, Vivienda, Rastreador de presas, Brújula, Consumibles, Vuelo dinámico y Misiones del mundo se desactivan de forma segura en Forever antes de iniciarse y se mantienen apagados en valores predeterminados, perfiles, importaciones y controles directos.",
    ["wn_406_forever_interface"] = "Cambio — Las páginas de opciones, pestañas QOL y la entrada del Estudio Mítico+ no disponibles se eliminan en Forever. Un aviso al iniciar sesión explica las limitaciones y /tm flavor muestra el cliente detectado y las decisiones de compatibilidad.",
    ["wn_406_forever_validation"] = "Interno — Un banco específico de 167 comprobaciones valida la detección del cliente, la aplicación sobre la base de datos, la coherencia entre manifiesto y valores predeterminados y las protecciones de cada módulo bloqueado.",
    ["wn_406_forever_actionbars"] = "Corrección — Las barras de acción gestionadas omiten ahora los eventos de Modo Desafío no disponibles en WoW: Forever. Registrar un evento no válido podía interrumpir la inicialización antes de crear ninguna barra, aunque el módulo ya figurase como inicializado.",
    ["wn_406_minimap_layout_drag"] = "Corrección — La capa de la minimapa ahora es una superficie de arrastre real de TomoLayout en lugar de una simple capa visual sobre el marco nativo. La minimapa puede seleccionarse y moverse de forma fiable desde el modo Layout aunque el modo Edición de Blizzard aún no se haya cargado.",
    ["wn_406_minimap_drag_guard"] = "Cambio — La protección de posición de la minimapa se pausa durante el arrastre, guarda la ubicación final al soltarla y después vuelve a protegerla frente a cambios posteriores del diseño de Blizzard.",
    ["wn_406_gear_weight_import"] = "Novedad — TomoGear V1.2 puede importar escalas Pawn v1, Ask Mr. Robot y key=value compatibles para la especialización actual. Se admiten la estadística principal, Aguante, Crítico, Celeridad, Maestría y Versatilidad.",
    ["wn_406_gear_import_gui"] = "Corrección — Se ha restaurado el flujo de importación completo de TomoGear en la pestaña QOL del Asesor de equipo, con el modo Importado, el editor multilínea, el estado y las acciones para importar o eliminar. El perfil y el estado se actualizan de inmediato.",
    ["wn_406_gear_import_validation"] = "Novedad — Cada especialización conserva su propio perfil importado. Se rechazan las escalas de otra clase, especialización o estadística principal, se ignoran los valores no compatibles y el nivel de objeto no recibe peso implícito sin ItemLevel=.",
    ["wn_406_gear_independent_db"] = "Cambio — Las preferencias y los pesos de TomoGear ahora residen en la variable guardada independiente TomoGearDB, al margen de los perfiles e importaciones de TomoMod. Los ajustes existentes del asesor se migran automáticamente una sola vez.",
    ["wn_406_gear_signed_percent"] = "Cambio — Las descripciones de objetos ahora muestran porcentajes con signo para mejoras, empeoramientos y objetos equivalentes en verde, rojo y color neutro. El umbral mínimo solo se aplica a la flecha de las bolsas.",
    ["wn_406_gear_itemref"] = "Corrección — Abrir un enlace de objeto desde el chat ya no provoca el error 'attempt to call a nil value' cuando ItemRefTooltip llega al posprocesador de objetos sin un método AddLine accesible para addons en algunas versiones de Midnight.",
    ["wn_406_gear_tooltip_guard"] = "Cambio — TomoGear ahora comprueba si la descripción admite líneas adicionales y aísla cada inserción de consejo. Las implementaciones incompatibles se omiten de forma segura, mientras que la ruta normal de GameTooltip permanece sin cambios.",
    ["wn_406_mplus_score_totals"] = "Corrección — TomoScore ahora lee el daño, la sanación y las interrupciones de las sesiones globales de toda la partida del medidor de daño con los tipos correctos. Los jugadores se asocian por GUID legible o por nombre, así que el resumen ya no permanece a cero por consultar el desglose de una fuente en vez de la lista de jugadores.",
    ["wn_406_secret_value_safety"] = "Corrección — Los nombres, texturas y tiempos de Mítico+, los niveles de objeto de la Gran Cámara, el historial de recorridos y los GUID de muertes, además de los GUID de misión de las placas de nombre, se comprueban antes de comparar, formatear o indexar. Los datos protegidos usan ahora un valor seguro en vez de provocar un error.",
    ["wn_406_leveling_max_level"] = "Corrección — La barra de experiencia ahora respeta el nivel 60 en WoW: Forever y el límite de Retail indicado por el cliente, incluido el nivel 90 en Midnight. Al alcanzar el máximo se oculta de inmediato y restaura la barra de Blizzard sin errores por una global nil.",
    ["wn_406_localized_commands_diag"] = "Cambio — Los mensajes de los comandos de módulos, copias de seguridad, diseño, resolución y ayuda están localizados en los seis idiomas compatibles. /tdm diag también ejecuta correctamente su prueba de legibilidad del medidor de daño de forma inmediata y en el siguiente fotograma, en vez de no hacer nada.",
    ["wn_406_actionbar_diagnostics"] = "Novedad — Los informes de diagnóstico incluyen ahora una sección de Barras de acción de solo lectura que muestra el estado del contenedor de cada barra, su controlador seguro de visibilidad y el resultado actual, el anclaje, el marco de movimiento, el total de botones y los datos de acción e icono del primer botón.",
    ["wn_406_actionbar_probe_safety"] = "Cambio — Las condiciones de ocultación forzada, el estado de C_ActionBar y los fallos silenciosos de SafeCall se indican ahora de forma explícita. La prueba sigue siendo segura en combate y se adapta correctamente cuando no hay API, métodos de marco o valores disponibles.",
    ["wn_406_actionbar_secure_wiring"] = "Novedad — La prueba de Barras de acción comprueba ahora directamente Execute, SetFrameRef y GetFrameRef restringido, e informa de las referencias seguras de diseño de cada barra, su estado de protección y los atributos de acción del primer botón. Así distingue un fallo general del controlador seguro de un enlace perdido durante la creación de las barras.",
    ["wn_406_early_error_capture"] = "Cambio — Diagnóstico captura ahora los errores relevantes de TomoMod y del controlador restringido desde la carga inicial hasta PLAYER_LOGIN, los reenvía al controlador anterior y marca las entradas conservadas como [during load]. Los fallos durante ADDON_LOADED ya no pueden generar un informe engañoso con cero errores.",
    ["wn_406_actionbar_compat_gate"] = "Corrección — Las versiones de WoW: Forever sin el compilador de código restringido de Blizzard detienen ahora el motor de Barras de acción antes de iniciarlo y mantienen inactiva la Barra de tótems. Las barras nativas de Blizzard siguen disponibles en lugar de ser reemplazadas por barras personalizadas cuyo diseño seguro no puede ejecutarse.",
    ["wn_406_actionbar_retail_profile_hotfix"] = "Corrección — Los perfiles de Retail con el interruptor principal guardado de las Barras de acción desactivado ya no pierden todas las barras propias tras recargar. El parche de compatibilidad de Forever conserva el comportamiento histórico de Retail y solo bloquea el motor cuando el cliente no puede ejecutar código restringido.",
    ["wn_406_actionbar_block_diagnostics"] = "Cambio — La protección de Forever se basa en las capacidades del cliente, conserva los ajustes de las Barras de acción y la Barra de tótems, y se libera automáticamente si vuelve la ejecución restringida. Diagnóstico muestra por separado la protección del cliente y el valor guardado del interruptor principal.",
    ["wn_406_slider_decimal_input"] = "Corrección — La entrada directa de los deslizadores mediante clic derecho acepta ahora comas decimales como 0,5 en vez de llevar el valor al mínimo. La indicación para introducir valores y restablecer con Ctrl+clic está traducida a los seis idiomas compatibles.",
    ["wn_406_astralforge_cleanup"] = "Corrección — Astral Forge ya no crea antes de tiempo un envoltorio global CommitFrameEdit alrededor de una función local aún no declarada. Las vistas de paridad de las placas de nombre siguen actualizándose mediante la reconstrucción existente del sujeto.",
    ["wn_406_asset_cleanup"] = "Cambio — Se actualizaron las seis texturas activas de los skins de iconos y se eliminaron del paquete los gráficos obsoletos de recursos de clase, la máscara de brillo sin uso y el sonido Taluani retirado.",
    ["wn_406_static_analysis"] = "Interno — Luacheck reconoce ahora las globales actuales del addon y los entornos aislados de TUI y pruebas. Se eliminaron de la referencia de publicación ocho avisos de valores protegidos ya resueltos.",
})

TomoMod_RegisterLocale("itIT", {
    ["wn_406_forever_detection"] = "Novità — TomoMod ora riconosce WoW: Forever come tipo di client distinto combinando l'identificatore del progetto moderno con la versione 1.60 o l'interfaccia 16001, senza confonderlo con Classic Era o Mists Classic.",
    ["wn_406_forever_modules"] = "Modifica — Mitica+, Alloggi, Tracciatore di prede, Bussola, Consumabili, Volo dinamico e Missioni mondiali vengono disattivati in sicurezza su Forever prima dell'inizializzazione e mantenuti spenti nei valori predefiniti, profili, importazioni e controlli diretti.",
    ["wn_406_forever_interface"] = "Modifica — Le pagine delle opzioni, le schede QOL e la voce dello Studio Mitica+ non disponibili vengono rimosse su Forever. Un avviso all'accesso spiega le limitazioni e /tm flavor mostra il client rilevato e le decisioni di compatibilità.",
    ["wn_406_forever_validation"] = "Interno — Un banco dedicato con 167 controlli verifica il rilevamento del client, l'applicazione al database, la coerenza tra manifest e valori predefiniti e le protezioni di ogni modulo bloccato.",
    ["wn_406_forever_actionbars"] = "Correzione — Le barre delle azioni gestite ora ignorano gli eventi Modalità Sfida non disponibili in WoW: Forever. La registrazione di un evento non valido poteva interrompere l'inizializzazione prima della creazione di qualsiasi barra, anche se il modulo risultava già inizializzato.",
    ["wn_406_minimap_layout_drag"] = "Correzione — La sovrapposizione della minimappa è ora una vera superficie di trascinamento TomoLayout invece di un semplice livello visivo sopra il riquadro nativo. La minimappa può essere selezionata e spostata in modo affidabile dalla modalità Layout anche se la modalità Modifica di Blizzard non è ancora caricata.",
    ["wn_406_minimap_drag_guard"] = "Modifica — La protezione della posizione della minimappa viene sospesa durante il trascinamento, salva la posizione finale al rilascio e poi riprende a proteggerla dalle successive modifiche del layout di Blizzard.",
    ["wn_406_gear_weight_import"] = "Novità — TomoGear V1.2 può importare scale Pawn v1, Ask Mr. Robot e key=value compatibili per la specializzazione attuale. Sono supportati statistica primaria, Tempra, Critico, Celerità, Maestria e Versatilità.",
    ["wn_406_gear_import_gui"] = "Correzione — Il flusso di importazione completo di TomoGear è stato ripristinato nella scheda QOL del Consigliere equipaggiamento, con modalità Importata, editor multilinea, stato e azioni di importazione o rimozione. Profilo e stato si aggiornano immediatamente.",
    ["wn_406_gear_import_validation"] = "Novità — Ogni specializzazione conserva il proprio profilo importato. Le scale con classe, specializzazione o statistica primaria errate vengono rifiutate, i valori non supportati ignorati e il livello oggetto non riceve alcun peso implicito senza ItemLevel=.",
    ["wn_406_gear_independent_db"] = "Modifica — Preferenze e pesi di TomoGear ora risiedono nella variabile salvata dedicata TomoGearDB, indipendentemente dai profili e dalle importazioni di TomoMod. Le impostazioni esistenti vengono migrate automaticamente una sola volta.",
    ["wn_406_gear_signed_percent"] = "Modifica — I tooltip degli oggetti mostrano ora percentuali con segno per miglioramenti, peggioramenti e oggetti equivalenti in verde, rosso e colore neutro. La soglia minima si applica soltanto alla freccia nelle borse.",
    ["wn_406_gear_itemref"] = "Correzione — L'apertura di un collegamento a un oggetto dalla chat non genera più l'errore 'attempt to call a nil value' quando ItemRefTooltip raggiunge il post-processore degli oggetti senza un metodo AddLine accessibile agli addon in alcune versioni di Midnight.",
    ["wn_406_gear_tooltip_guard"] = "Modifica — TomoGear ora verifica che il tooltip supporti l'aggiunta di righe e protegge ogni inserimento dei consigli. Le implementazioni non supportate vengono ignorate in sicurezza, mentre il normale percorso GameTooltip resta invariato.",
    ["wn_406_mplus_score_totals"] = "Correzione — TomoScore ora legge danni, cure e interruzioni dalle sessioni Overall dell'intera spedizione del Damage Meter usando i tipi corretti. I giocatori vengono associati tramite GUID leggibile o nome, quindi il riepilogo non resta più a zero perché interrogava il dettaglio di una sorgente invece dell'elenco dei giocatori.",
    ["wn_406_secret_value_safety"] = "Correzione — Nomi, texture e tempi Mitica+, livelli oggetto della Gran Banca, cronologia delle spedizioni e GUID delle morti, oltre ai GUID missione delle barre dei nomi, vengono controllati prima di confronti, formattazione o indicizzazione. I dati protetti ora usano un ripiego sicuro invece di generare errori.",
    ["wn_406_leveling_max_level"] = "Correzione — La barra dell'esperienza ora rispetta il livello 60 in WoW: Forever e il limite Retail comunicato dal client, compreso il livello 90 in Midnight. Al raggiungimento del limite si nasconde subito e ripristina la barra di Blizzard senza errori dovuti a una globale nil.",
    ["wn_406_localized_commands_diag"] = "Modifica — I messaggi dei comandi per moduli, backup, layout, risoluzione e aiuto sono ora tradotti in tutte e sei le lingue supportate. /tdm diag esegue inoltre correttamente il controllo di leggibilità del Damage Meter subito e nel fotogramma successivo, invece di non fare nulla.",
    ["wn_406_actionbar_diagnostics"] = "Novità — I rapporti diagnostici includono ora una sezione Barre delle azioni di sola lettura che mostra lo stato del contenitore di ogni barra, il driver di visibilità protetto con il risultato corrente, l'ancoraggio, il riquadro di spostamento, il totale dei pulsanti e i dati di azione e icona del primo pulsante.",
    ["wn_406_actionbar_probe_safety"] = "Modifica — Le condizioni di occultamento forzato, lo stato di C_ActionBar e gli errori SafeCall silenziosi vengono ora segnalati esplicitamente. La sonda resta sicura in combattimento e si adatta correttamente quando API, metodi dei riquadri o valori non sono disponibili.",
    ["wn_406_actionbar_secure_wiring"] = "Novità — La sonda delle barre delle azioni verifica ora direttamente Execute, SetFrameRef e GetFrameRef in ambiente protetto, e segnala i riferimenti protetti del layout di ogni barra, lo stato di protezione e gli attributi azione del primo pulsante. In questo modo distingue un guasto generale del gestore protetto da un collegamento perso durante la creazione delle barre.",
    ["wn_406_early_error_capture"] = "Modifica — La diagnostica acquisisce ora gli errori rilevanti di TomoMod e del gestore protetto dal caricamento iniziale fino a PLAYER_LOGIN, li inoltra al gestore precedente e contrassegna le voci conservate con [during load]. Gli errori durante ADDON_LOADED non possono più produrre un rapporto ingannevole con zero errori.",
    ["wn_406_actionbar_compat_gate"] = "Correzione — Le versioni di WoW: Forever prive del compilatore di codice protetto di Blizzard arrestano ora il motore delle barre delle azioni prima dell'inizializzazione e mantengono inattiva la barra dei totem. Le barre native di Blizzard restano disponibili invece di essere sostituite da barre personalizzate il cui layout protetto non può funzionare.",
    ["wn_406_actionbar_retail_profile_hotfix"] = "Correzione — I profili Retail con l'interruttore principale salvato delle barre delle azioni disattivato non perdono più tutte le barre personalizzate dopo un riavvio dell'interfaccia. La correzione di compatibilità di Forever conserva il comportamento storico su Retail e blocca il motore solo se il client non può eseguire codice protetto.",
    ["wn_406_actionbar_block_diagnostics"] = "Modifica — Il blocco di Forever si basa sulle capacità del client, conserva le impostazioni delle barre delle azioni e dei totem e si disattiva automaticamente se torna l'esecuzione protetta. La diagnostica mostra separatamente il blocco del client e il valore salvato dell'interruttore principale.",
    ["wn_406_slider_decimal_input"] = "Correzione — L'inserimento diretto dei valori con clic destro accetta ora le virgole decimali come 0,5 invece di portare il cursore al minimo. Il suggerimento per l'inserimento e il ripristino con Ctrl+clic è tradotto in tutte e sei le lingue supportate.",
    ["wn_406_astralforge_cleanup"] = "Correzione — Astral Forge non crea più in anticipo un wrapper globale CommitFrameEdit attorno a una funzione locale non ancora dichiarata. Le anteprime di parità delle barre dei nomi continuano ad aggiornarsi tramite la ricostruzione esistente del soggetto.",
    ["wn_406_asset_cleanup"] = "Modifica — Le sei texture attive delle skin delle icone sono state aggiornate; le vecchie grafiche delle risorse di classe, la maschera del bagliore inutilizzata e il suono Taluani ritirato sono stati rimossi dal pacchetto.",
    ["wn_406_static_analysis"] = "Interno — Luacheck riconosce ora le globali attuali dell'addon e gli ambienti isolati di TUI e dei test. Otto segnalazioni risolte sui valori protetti sono state rimosse dalla baseline di pubblicazione.",
})

TomoMod_RegisterLocale("ptBR", {
    ["wn_406_forever_detection"] = "Novidade — O TomoMod agora reconhece o WoW: Forever como um tipo de cliente próprio ao combinar o identificador do projeto moderno com a versão 1.60 ou a interface 16001, sem confundi-lo com Classic Era ou Mists Classic.",
    ["wn_406_forever_modules"] = "Alteração — Mítico+, Moradia, Rastreador de presas, Bússola, Consumíveis, Voo dinâmico e Missões mundiais são desativados com segurança no Forever antes da inicialização e mantidos desligados nos padrões, perfis, importações e controles diretos.",
    ["wn_406_forever_interface"] = "Alteração — Páginas de opções, abas QOL e a entrada do Estúdio Mítico+ indisponíveis são removidas no Forever. Um aviso ao entrar explica as limitações, e /tm flavor mostra o cliente detectado e as decisões de compatibilidade.",
    ["wn_406_forever_validation"] = "Interno — Um conjunto dedicado de 167 verificações valida a detecção do cliente, a aplicação no banco de dados, a consistência entre manifesto e padrões e as proteções de cada módulo bloqueado.",
    ["wn_406_forever_actionbars"] = "Correção — As barras de ação gerenciadas agora ignoram os eventos de Modo Desafio indisponíveis no WoW: Forever. O registro de um evento inválido podia interromper a inicialização antes da criação de qualquer barra, embora o módulo já estivesse marcado como inicializado.",
    ["wn_406_minimap_layout_drag"] = "Correção — A sobreposição do minimapa agora é uma superfície real de arraste do TomoLayout, em vez de apenas uma camada visual sobre o quadro nativo. O minimapa pode ser selecionado e movido de forma confiável no modo Layout mesmo que o modo de Edição da Blizzard ainda não tenha sido carregado.",
    ["wn_406_minimap_drag_guard"] = "Alteração — A proteção da posição do minimapa pausa durante o arraste, salva o local final ao soltar e depois volta a protegê-lo contra alterações posteriores do layout da Blizzard.",
    ["wn_406_gear_weight_import"] = "Novidade — O TomoGear V1.2 pode importar escalas Pawn v1, Ask Mr. Robot e key=value compatíveis para a especialização atual. Atributo primário, Vigor, Crítico, Aceleração, Maestria e Versatilidade são aceitos.",
    ["wn_406_gear_import_gui"] = "Correção — O fluxo completo de importação do TomoGear foi restaurado na aba QOL do Consultor de equipamentos, com modo Importado, editor multilinha, status e ações para importar ou remover. O perfil e o status agora são atualizados imediatamente.",
    ["wn_406_gear_import_validation"] = "Novidade — Cada especialização mantém seu próprio perfil importado. Escalas com classe, especialização ou atributo primário incompatíveis são recusadas, valores não aceitos são ignorados e o nível do item não recebe peso implícito sem ItemLevel=.",
    ["wn_406_gear_independent_db"] = "Alteração — As preferências e os pesos do TomoGear agora ficam na variável salva dedicada TomoGearDB, independentemente dos perfis e das importações do TomoMod. As configurações existentes são migradas automaticamente uma única vez.",
    ["wn_406_gear_signed_percent"] = "Alteração — As dicas de item agora mostram percentuais com sinal para melhorias, pioras e itens equivalentes em verde, vermelho e cor neutra. O limite mínimo se aplica apenas à seta nas bolsas.",
    ["wn_406_gear_itemref"] = "Correção — Abrir um link de item pelo bate-papo não causa mais o erro 'attempt to call a nil value' quando o ItemRefTooltip chega ao pós-processador de itens sem um método AddLine acessível a addons em algumas versões do Midnight.",
    ["wn_406_gear_tooltip_guard"] = "Alteração — O TomoGear agora verifica se a dica aceita linhas adicionais e protege cada inserção de recomendação. Implementações incompatíveis são ignoradas com segurança, enquanto o fluxo normal do GameTooltip permanece inalterado.",
    ["wn_406_mplus_score_totals"] = "Correção — O TomoScore agora lê dano, cura e interrupções das sessões Overall de toda a masmorra do Damage Meter usando os tipos corretos. Os jogadores são associados por GUID legível ou nome, então o resumo não permanece mais zerado por consultar o detalhamento de uma fonte em vez da lista de jogadores.",
    ["wn_406_secret_value_safety"] = "Correção — Nomes, texturas e limites de tempo de Mítico+, níveis de item do Grande Cofre, histórico de runs e GUIDs de mortes, além dos GUIDs de missão das placas de nome, são verificados antes de comparação, formatação ou indexação. Dados protegidos agora usam um valor seguro em vez de causar erro.",
    ["wn_406_leveling_max_level"] = "Correção — A barra de experiência agora respeita o nível 60 no WoW: Forever e o limite de Retail informado pelo cliente, incluindo o nível 90 no Midnight. Ao atingir o limite, ela some imediatamente e restaura a barra da Blizzard sem erro de global nil.",
    ["wn_406_localized_commands_diag"] = "Alteração — As mensagens dos comandos de módulos, backup, layout, resolução e ajuda agora estão localizadas nos seis idiomas compatíveis. /tdm diag também executa corretamente sua verificação de leitura do Damage Meter de forma imediata e no quadro seguinte, em vez de não fazer nada.",
    ["wn_406_actionbar_diagnostics"] = "Novidade — Os relatórios de diagnóstico agora incluem uma seção Barras de ação somente para leitura, mostrando o estado do contêiner de cada barra, o controlador seguro de visibilidade e seu resultado atual, a âncora, o quadro de movimentação, o total de botões e os dados de ação e ícone do primeiro botão.",
    ["wn_406_actionbar_probe_safety"] = "Alteração — As condições de ocultação forçada, o estado de C_ActionBar e as falhas silenciosas de SafeCall agora são informados explicitamente. A sondagem permanece segura em combate e se adapta corretamente quando APIs, métodos de quadros ou valores não estão disponíveis.",
    ["wn_406_actionbar_secure_wiring"] = "Novidade — A sondagem das barras de ação agora testa diretamente Execute, SetFrameRef e GetFrameRef no ambiente restrito, e informa as referências seguras de layout de cada barra, o estado de proteção e os atributos de ação do primeiro botão. Assim, ela distingue uma falha geral do controlador seguro de uma ligação perdida durante a criação das barras.",
    ["wn_406_early_error_capture"] = "Alteração — O diagnóstico agora captura erros relevantes do TomoMod e do controlador restrito desde o carregamento inicial até PLAYER_LOGIN, encaminha-os ao controlador anterior e marca as entradas mantidas como [during load]. Falhas durante ADDON_LOADED não podem mais gerar um relatório enganoso com zero erros.",
    ["wn_406_actionbar_compat_gate"] = "Correção — As versões do WoW: Forever sem o compilador de código restrito da Blizzard agora interrompem o mecanismo das Barras de Ação antes da inicialização e mantêm a Barra de Totens inativa. As barras nativas da Blizzard continuam disponíveis, em vez de serem substituídas por barras personalizadas cujo layout seguro não pode funcionar.",
    ["wn_406_actionbar_retail_profile_hotfix"] = "Correção — Perfis de Retail com o controle principal salvo das Barras de Ação desativado não perdem mais todas as barras próprias após recarregar. A correção de compatibilidade do Forever preserva o comportamento histórico no Retail e só bloqueia o mecanismo quando o cliente não consegue executar código restrito.",
    ["wn_406_actionbar_block_diagnostics"] = "Alteração — O bloqueio do Forever se baseia nos recursos do cliente, preserva as configurações das Barras de Ação e da Barra de Totens e é liberado automaticamente se a execução restrita retornar. O diagnóstico mostra separadamente o bloqueio do cliente e o valor salvo do controle principal.",
    ["wn_406_slider_decimal_input"] = "Correção — A entrada direta dos controles deslizantes por clique direito agora aceita vírgulas decimais como 0,5, em vez de levar o valor ao mínimo. A dica para inserir valores e redefinir com Ctrl+clique está traduzida nos seis idiomas compatíveis.",
    ["wn_406_astralforge_cleanup"] = "Correção — O Astral Forge não cria mais antecipadamente um wrapper global CommitFrameEdit em torno de uma função local ainda não declarada. As prévias de paridade das placas de nome continuam sendo atualizadas pelo fluxo existente de reconstrução do sujeito.",
    ["wn_406_asset_cleanup"] = "Alteração — As seis texturas ativas dos skins de ícones foram atualizadas; artes antigas de recursos de classe, a máscara de brilho sem uso e o som Taluani descontinuado foram removidos do pacote.",
    ["wn_406_static_analysis"] = "Interno — O Luacheck agora reconhece as globais atuais do addon e os ambientes isolados da TUI e dos testes. Oito ocorrências resolvidas de valores protegidos foram removidas da baseline de lançamento.",
})
